//! The seeded test vectors (§3.7): `tests/vectors/v4.json`, regenerated by
//! `examples/gen_vectors.rs` and checked byte for byte by `tests/vectors.rs`
//! and in CI. The Kotlin and wasm round trips (PR-2) replay the same seeds.
//!
//! Every wire message is the exact WebSocket payload, kind byte included, in
//! lowercase hex (text messages are the hex of their UTF-8 bytes).

use std::{
    collections::VecDeque,
    sync::{Arc, Mutex, RwLock},
};

use curve25519_dalek::{
    constants::{ED25519_BASEPOINT_POINT, EIGHT_TORSION},
    edwards::CompressedEdwardsY,
    scalar::Scalar,
};
use serde_json::{Map, Value, json};

use crate::{
    HubConnection, LEGACY_DENIAL, Outgoing, PairingGate, PinSet, RelayEvent, RemoteConnection,
    StaticKeypair, Step, WsIn, keys::hex_lower as hex, pake::ElementRejection,
    test_support::test_seed,
};

/// The clock the vectors start at.
pub const T0: u64 = 1_000_000;
/// The hub's display name in the vectors.
pub const HUB_NAME: &str = "Kitchen tablet";
/// The remote's display name in the vectors.
pub const REMOTE_NAME: &str = "Pixel 8";
/// The rekey interval of the rekey vector.
pub const REKEY_TEST_INTERVAL: u64 = 4;
/// The large message's length.
pub const LARGE_MESSAGE_LEN: usize = 200_000;
/// The `Welcome` frame the hub sends first in the resume vector.
pub const WELCOME_FRAME: &str = r#"{"type":"welcome","primaryName":"Kitchen tablet","authority":"primary","roster":[],"scope":"control"}"#;

/// The large message: byte `i` is `i mod 251`.
pub fn large_message() -> Vec<u8> {
    (0..LARGE_MESSAGE_LEN)
        .map(|i| u8::try_from(i % 251).unwrap_or(0))
        .collect()
}

/// The X25519 low-order points: the canonical u-coordinates 0, 1, the two of
/// order 8 and p − 1; the non-canonical p and p + 1; and the same seven with
/// bit 255 set (X25519 ignores it).
pub fn low_order_keys() -> Vec<[u8; 32]> {
    let mut canonical: Vec<[u8; 32]> = Vec::new();
    let mut small = [0_u8; 32];
    canonical.push(small);
    small[0] = 1;
    canonical.push(small);
    canonical.push(from_hex32(
        "e0eb7a7c3b41b8ae1656e3faf19fc46ada098deb9c32b1fd866205165f49b800",
    ));
    canonical.push(from_hex32(
        "5f9c95bca3508c24b1d0b1559c83ef5b04445cc4581c8e86d8224eddd09f1157",
    ));
    for low in [0xec_u8, 0xed, 0xee] {
        // p − 1, p, p + 1 (p = 2^255 − 19, little-endian)
        let mut v = [0xff_u8; 32];
        v[0] = low;
        v[31] = 0x7f;
        canonical.push(v);
    }
    let mut all = canonical.clone();
    for mut v in canonical {
        v[31] |= 0x80;
        all.push(v);
    }
    all
}

fn from_hex32(s: &str) -> [u8; 32] {
    let mut out = [0_u8; 32];
    for (i, o) in out.iter_mut().enumerate() {
        *o = u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap_or(0);
    }
    out
}

/// One negative SPAKE2 element vector.
pub struct BadElement {
    /// What it is.
    pub name: String,
    /// The SPAKE2 message as the hub would receive it in `PAKE_A`.
    pub message: Vec<u8>,
    /// The check that must reject it.
    pub rejected_by: ElementRejection,
}

/// `p + k` as a little-endian y-coordinate (p = 2^255 − 19 ends in 0xed).
fn p_plus(k: u8) -> [u8; 32] {
    let mut v = [0xff_u8; 32];
    v[0] = 0xed + k;
    v[31] = 0x7f;
    v
}

fn element_message(side: u8, encoded: &[u8; 32]) -> Vec<u8> {
    let mut m = vec![side];
    m.extend_from_slice(encoded);
    m
}

/// The `bad_elements` vectors (§3.7).
pub fn bad_elements() -> Vec<BadElement> {
    let mut out = Vec::new();
    let mut identity = [0_u8; 32];
    identity[0] = 1;
    out.push(BadElement {
        name: "identity".into(),
        message: element_message(b'A', &identity),
        rejected_by: ElementRejection::Identity,
    });
    out.push(BadElement {
        name: "y = p+1 (non-canonical identity)".into(),
        message: element_message(b'A', &p_plus(1)),
        rejected_by: ElementRejection::NonCanonical,
    });
    out.push(BadElement {
        name: "y = p+3 (non-canonical, torsioned)".into(),
        message: element_message(b'A', &p_plus(3)),
        rejected_by: ElementRejection::NonCanonical,
    });
    for (i, t) in EIGHT_TORSION.iter().enumerate() {
        let rejected_by = if i == 0 {
            ElementRejection::Identity
        } else {
            ElementRejection::Torsion
        };
        out.push(BadElement {
            name: format!("small-order point {i}"),
            message: element_message(b'A', &t.compress().to_bytes()),
            rejected_by,
        });
    }
    let honest = ED25519_BASEPOINT_POINT * Scalar::from(7_u64);
    let torsioned = honest + EIGHT_TORSION[2];
    out.push(BadElement {
        name: "7G + T4 (torsioned)".into(),
        message: element_message(b'A', &torsioned.compress().to_bytes()),
        rejected_by: ElementRejection::Torsion,
    });
    out.push(BadElement {
        name: "honest element, wrong side byte".into(),
        message: element_message(b'B', &honest.compress().to_bytes()),
        rejected_by: ElementRejection::Side,
    });
    // The smallest y ≥ 2 that isn't on the curve.
    let mut y = 2_u8;
    let off_curve = loop {
        let mut enc = [0_u8; 32];
        enc[0] = y;
        if CompressedEdwardsY(enc).decompress().is_none() {
            break enc;
        }
        y += 1;
    };
    out.push(BadElement {
        name: format!("y = {y} (not on the curve)"),
        message: element_message(b'A', &off_curve),
        rejected_by: ElementRejection::Decompress,
    });
    let mut short = element_message(b'A', &honest.compress().to_bytes());
    short.pop();
    out.push(BadElement {
        name: "32 bytes (short)".into(),
        message: short,
        rejected_by: ElementRejection::Length,
    });
    out
}

/// Two connections joined in memory, recording every message.
struct Run {
    hub: HubConnection,
    remote: RemoteConnection,
    now: u64,
    queue: VecDeque<(bool, Outgoing)>,
    log: Vec<(bool, Outgoing)>,
    remote_events: Vec<RelayEvent>,
    remote_delivered: Vec<Vec<u8>>,
    hub_closed: bool,
    remote_closed: bool,
}

impl Run {
    fn new(hub: HubConnection, remote: RemoteConnection, first: Step) -> Self {
        let mut run = Self {
            hub,
            remote,
            now: T0,
            queue: VecDeque::new(),
            log: Vec::new(),
            remote_events: Vec::new(),
            remote_delivered: Vec::new(),
            hub_closed: false,
            remote_closed: false,
        };
        run.take_remote(first);
        run
    }

    fn take_hub(&mut self, step: Step) {
        for m in step.send {
            self.log.push((false, m.clone()));
            self.queue.push_back((false, m));
        }
        self.hub_closed |= step.close.is_some();
    }

    fn take_remote(&mut self, step: Step) {
        for m in step.send {
            self.log.push((true, m.clone()));
            self.queue.push_back((true, m));
        }
        self.remote_events.extend(step.events);
        self.remote_delivered.extend(step.deliver);
        self.remote_closed |= step.close.is_some();
    }

    fn pump(&mut self) {
        while let Some((to_hub, m)) = self.queue.pop_front() {
            let input = if m.text {
                WsIn::Text(&m.bytes)
            } else {
                WsIn::Binary(&m.bytes)
            };
            if to_hub && !self.hub_closed {
                let step = self.hub.on_ws(input, self.now);
                self.take_hub(step);
            } else if !to_hub && !self.remote_closed {
                let step = self.remote.on_ws(input, self.now);
                self.take_remote(step);
            }
        }
    }

    fn mark(&self) -> usize {
        self.log.len()
    }

    fn since(&self, mark: usize) -> Vec<String> {
        self.log[mark..]
            .iter()
            .map(|(_, m)| hex(&m.bytes))
            .collect()
    }

    fn first_text(&self) -> String {
        String::from_utf8_lossy(&self.log[0].1.bytes).into_owned()
    }

    fn code(&self) -> String {
        self.remote_events
            .iter()
            .find_map(|e| match e {
                RelayEvent::ShowCode { code, .. } => Some(code.clone()),
                _ => None,
            })
            .unwrap_or_default()
    }

    fn hub_send(&mut self, message: &[u8]) {
        if let Ok(step) = self.hub.send(message, self.now) {
            self.take_hub(step);
        }
        self.pump();
    }
}

fn key_json(k: &StaticKeypair) -> Value {
    json!({
        "private": hex(k.private_for_storage().as_ref()),
        "public": hex(&k.public()),
        "device_id": k.device_id().to_hex(),
        "short_id": k.device_id().short(),
    })
}

fn named(log: &[String], keys: &[&str]) -> Map<String, Value> {
    keys.iter()
        .zip(log)
        .map(|(k, v)| ((*k).to_owned(), Value::String(v.clone())))
        .collect()
}

fn gate(open: bool) -> Arc<Mutex<PairingGate>> {
    let mut gate = PairingGate::new();
    if open {
        let _ = gate.open(T0);
    }
    Arc::new(Mutex::new(gate))
}

fn pins(keys: Vec<[u8; 32]>) -> Arc<RwLock<PinSet>> {
    Arc::new(RwLock::new(PinSet::new(keys).unwrap_or_default()))
}

fn hub_for(
    keys: &StaticKeypair,
    gate: &Arc<Mutex<PairingGate>>,
    pins: &Arc<RwLock<PinSet>>,
    n: u32,
) -> HubConnection {
    HubConnection::new(
        keys,
        Arc::clone(gate),
        Arc::clone(pins),
        HUB_NAME,
        test_seed("hub-conn", n),
        T0,
    )
}

fn binding_hex(h: Option<[u8; 32]>) -> Value {
    Value::String(h.map(|h| hex(&h)).unwrap_or_default())
}

fn pairing(remote_keys: &StaticKeypair, hub_keys: &StaticKeypair) -> Value {
    let gate = gate(true);
    let pins = pins(vec![]);
    let hub = hub_for(hub_keys, &gate, &pins, 0);
    let (remote, first) =
        RemoteConnection::pair(remote_keys, REMOTE_NAME, test_seed("remote-conn", 0), T0);
    let mut run = Run::new(hub, remote, first);
    run.pump();
    let code = run.code();
    if let Ok(step) = run.hub.enter_code(&code, run.now) {
        run.take_hub(step);
    }
    run.pump();
    if let (Some(key), Ok(mut p)) = (run.hub.peer_public_key(), pins.write()) {
        let _ = p.insert(key);
    }
    if let Ok(step) = run.hub.confirm_paired(run.now) {
        run.take_hub(step);
    }
    run.pump();
    let mut obj = named(
        &run.since(0),
        &[
            "client_hello",
            "server_hello",
            "pake_a",
            "pake_b",
            "noise_1",
            "noise_2",
            "noise_3",
            "pair_complete",
        ],
    );
    obj.insert("client_hello_text".into(), Value::String(run.first_text()));
    obj.insert("code".into(), Value::String(code));
    obj.insert(
        "psk".into(),
        Value::String(run.hub.psk_for_tests().map(|p| hex(&p)).unwrap_or_default()),
    );
    obj.insert(
        "channel_binding".into(),
        binding_hex(run.hub.channel_binding()),
    );
    obj.insert(
        "paired".into(),
        Value::Bool(
            run.remote_events
                .iter()
                .any(|e| matches!(e, RelayEvent::Paired { .. })),
        ),
    );
    obj.insert(
        "seeds".into(),
        json!({"remote": ["remote-conn", 0], "hub": ["hub-conn", 0]}),
    );
    Value::Object(obj)
}

fn resume(remote_keys: &StaticKeypair, hub_keys: &StaticKeypair) -> Value {
    let gate = gate(false);
    let pins = pins(vec![remote_keys.public()]);
    let hub = hub_for(hub_keys, &gate, &pins, 1);
    let (remote, first) = RemoteConnection::resume(
        remote_keys,
        hub_keys.public(),
        test_seed("remote-conn", 1),
        T0,
    );
    let mut run = Run::new(hub, remote, first);
    run.pump();
    let mut obj = named(
        &run.since(0),
        &[
            "client_hello",
            "server_hello",
            "ik_1",
            "ik_2",
            "client_finished",
        ],
    );
    obj.insert("client_hello_text".into(), Value::String(run.first_text()));
    let mark = run.mark();
    run.hub_send(WELCOME_FRAME.as_bytes());
    obj.insert("welcome_frame".into(), Value::String(WELCOME_FRAME.into()));
    obj.insert(
        "welcome_record".into(),
        Value::String(run.since(mark).concat()),
    );
    let mark = run.mark();
    run.hub_send(&large_message());
    obj.insert(
        "large_message".into(),
        json!({
            "direction": "hub_to_remote",
            "len": LARGE_MESSAGE_LEN,
            "content": "byte i = i mod 251",
            "records": run.since(mark),
        }),
    );
    let ok = run.remote_delivered == vec![WELCOME_FRAME.as_bytes().to_vec(), large_message()];
    obj.insert("delivered".into(), Value::Bool(ok));
    obj.insert(
        "channel_binding".into(),
        binding_hex(run.hub.channel_binding()),
    );
    obj.insert(
        "seeds".into(),
        json!({"remote": ["remote-conn", 1], "hub": ["hub-conn", 1]}),
    );
    Value::Object(obj)
}

fn rekey(remote_keys: &StaticKeypair, hub_keys: &StaticKeypair) -> Value {
    let gate = gate(false);
    let pins = pins(vec![remote_keys.public()]);
    let mut hub = hub_for(hub_keys, &gate, &pins, 2);
    hub.set_rekey_interval_for_tests(REKEY_TEST_INTERVAL);
    let (mut remote, first) = RemoteConnection::resume(
        remote_keys,
        hub_keys.public(),
        test_seed("remote-conn", 2),
        T0,
    );
    remote.set_rekey_interval_for_tests(REKEY_TEST_INTERVAL);
    let mut run = Run::new(hub, remote, first);
    run.pump();
    let mark = run.mark();
    let messages: Vec<String> = (0..6).map(|i| format!("rekey {i}")).collect();
    for m in &messages {
        run.hub_send(m.as_bytes());
    }
    let ok = run.remote_delivered
        == messages
            .iter()
            .map(|m| m.as_bytes().to_vec())
            .collect::<Vec<_>>();
    json!({
        "interval": REKEY_TEST_INTERVAL,
        "direction": "hub_to_remote",
        "messages": messages,
        "records": run.since(mark),
        "note": "the hub rekeys its sending key after the records with nonce 3 ((n + 1) % 4 == 0)",
        "delivered": ok,
        "seeds": {"remote": ["remote-conn", 2], "hub": ["hub-conn", 2]},
    })
}

fn wrong_code(remote_keys: &StaticKeypair, hub_keys: &StaticKeypair) -> Value {
    let gate = gate(true);
    let pins = pins(vec![]);
    let hub = hub_for(hub_keys, &gate, &pins, 3);
    let (remote, first) =
        RemoteConnection::pair(remote_keys, REMOTE_NAME, test_seed("remote-conn", 3), T0);
    let mut run = Run::new(hub, remote, first);
    run.pump();
    let shown = run.code();
    let entered: String = shown
        .bytes()
        .map(|b| char::from(b'0' + (b - b'0' + 1) % 10))
        .collect();
    if let Ok(step) = run.hub.enter_code(&entered, run.now) {
        run.take_hub(step);
    }
    run.pump();
    let hub_abort = run
        .log
        .iter()
        .rev()
        .find(|(to_hub, _)| !*to_hub)
        .map(|(_, m)| hex(&m.bytes))
        .unwrap_or_default();
    json!({
        "shown_code": shown,
        "entered_code": entered,
        "messages": run.since(0),
        "hub_abort": hub_abort,
        "seeds": {"remote": ["remote-conn", 3], "hub": ["hub-conn", 3]},
    })
}

/// The name of an element check, as the vectors spell it.
pub fn rejection_name(r: ElementRejection) -> &'static str {
    match r {
        ElementRejection::Length => "Length",
        ElementRejection::Side => "Side",
        ElementRejection::Decompress => "Decompress",
        ElementRejection::NonCanonical => "NonCanonical",
        ElementRejection::Identity => "Identity",
        ElementRejection::Torsion => "Torsion",
    }
}

/// The whole vector file.
pub fn build() -> Value {
    let remote_keys = StaticKeypair::generate(test_seed("remote-static", 0));
    let hub_keys = StaticKeypair::generate(test_seed("hub-static", 0));
    let seed_hex = |label: &str, n: u32| hex(&test_seed(label, n).0);
    json!({
        "format": "de1-relay v4 vectors; lowercase hex; wire messages are whole WebSocket payloads, kind byte included",
        "seed_rule": "SHA-256(\"de1-relay test seed \" || label || \" \" || n), n in decimal",
        "t0_ms": T0,
        "names": {"hub": HUB_NAME, "remote": REMOTE_NAME},
        "seeds": {
            "remote-static 0": seed_hex("remote-static", 0),
            "hub-static 0": seed_hex("hub-static", 0),
            "remote-conn 0": seed_hex("remote-conn", 0),
            "hub-conn 0": seed_hex("hub-conn", 0),
        },
        "keys": {"remote": key_json(&remote_keys), "hub": key_json(&hub_keys)},
        "pairing": pairing(&remote_keys, &hub_keys),
        "resume": resume(&remote_keys, &hub_keys),
        "rekey": rekey(&remote_keys, &hub_keys),
        "wrong_code": wrong_code(&remote_keys, &hub_keys),
        "legacy_denial": LEGACY_DENIAL,
        "bad_elements": bad_elements().into_iter().map(|b| json!({
            "name": b.name,
            "message": hex(&b.message),
            "rejected_by": rejection_name(b.rejected_by),
        })).collect::<Vec<_>>(),
        "low_order_keys": low_order_keys().iter().map(|k| hex(k)).collect::<Vec<_>>(),
    })
}

/// Regenerates `tests/vectors/v4.json` (pretty JSON, trailing newline).
pub fn generate() -> String {
    let mut s = serde_json::to_string_pretty(&build()).unwrap_or_default();
    s.push('\n');
    s
}
